// Enhanced Case Modal with tabbed interface and advanced animations
import React, {
  useState,
  useEffect,
  useMemo,
  useCallback,
  useRef,
  useLayoutEffect,
} from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  X,
  Users,
  FileText,
  Pill,
  Brain,
  Link2,
  Edit3,
  Trash2,
  Save,
  Loader2,
  Plus,
  Check,
  Calendar,
  Clock,
  AlertCircle,
  BookOpen,
  Target,
  Heart,
  ChevronDown,
  ChevronRight,
  Activity,
} from "lucide-react";

// Import the Vertical Timeline component
import VerticalTimeline from "./timeline-test/VerticalTimeline";
// Import Notes and Tags components
import NotesEditor from "./NotesEditor";
import TagManager from "./TagManager";

// Utility function for debouncing
const debounce = (func, delay) => {
  let timeoutId;
  return (...args) => {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => func.apply(null, args), delay);
  };
};

// Animation variants for Framer Motion
const modalVariants = {
  hidden: {
    opacity: 0,
    scale: 0.3,
    y: 50,
    rotate: -5,
  },
  visible: {
    opacity: 1,
    scale: 1,
    y: 0,
    rotate: 0,
    transition: {
      type: "spring",
      damping: 25,
      stiffness: 300,
      duration: 0.6,
    },
  },
  exit: {
    opacity: 0,
    scale: 0.7,
    y: 30,
    rotate: -3,
    transition: {
      type: "easeInOut",
      duration: 0.4,
    },
  },
};

const backdropVariants = {
  hidden: {
    opacity: 0,
    backdropFilter: "blur(0px)",
  },
  visible: {
    opacity: 1,
    backdropFilter: "blur(8px)",
    transition: {
      duration: 0.2,
      ease: "easeOut",
    },
  },
  exit: {
    opacity: 0,
    backdropFilter: "blur(0px)",
    transition: {
      duration: 0.15,
      ease: "easeInOut",
    },
  },
};

const contentVariants = {
  hidden: {
    opacity: 0,
    y: 20,
    scale: 0.95,
  },
  visible: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: {
      type: "spring",
      damping: 25,
      stiffness: 400,
      duration: 0.3,
    },
  },
  exit: {
    opacity: 0,
    y: -10,
    scale: 0.98,
    transition: {
      duration: 0.2,
      ease: "easeInOut",
    },
  },
};

// Card animation variants for sections
const cardVariants = {
  hidden: { opacity: 0, y: 20, scale: 0.95 },
  visible: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: {
      duration: 0.4,
      ease: "easeOut",
    },
  },
  edit: {
    scale: 1.02,
    boxShadow: "0 8px 25px rgba(59, 130, 246, 0.15)",
    transition: {
      duration: 0.3,
      ease: "easeOut",
    },
  },
  saved: {
    scale: 1,
    boxShadow: "0 4px 15px rgba(34, 197, 94, 0.15)",
    transition: {
      duration: 0.3,
      ease: "easeOut",
    },
  },
};

const CaseModal = ({
  isOpen,
  data,
  onClose,
  onAnimationStart,
  onAnimationEnd,
  allNodes = [],
  connections = [],
  setMindMapData,
  autoSaveMindMapData,
  addToast,
}) => {
  const [isAnimating, setIsAnimating] = useState(false);
  const [isVisible, setIsVisible] = useState(false);
  const [isClosing, setIsClosing] = useState(false);
  const [editData, setEditData] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const [hasInitialized, setHasInitialized] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");
  const [isTabTransitioning, setIsTabTransitioning] = useState(false);

  // Individual section edit states
  const [editingSections, setEditingSections] = useState({});
  const [sectionData, setSectionData] = useState({});

  // Tab-specific scroll positions
  const [scrollPositions, setScrollPositions] = useState({});
  const contentRefs = useRef({});
  // Height animation state for smooth vertical resize
  const [contentHeight, setContentHeight] = useState("auto");
  const contentWrapperRef = useRef(null);
  // Refs to measure chrome (header + tabs) to compute available height
  const headerRef = useRef(null);
  const tabsRef = useRef(null);
  const viewportHRef = useRef(
    typeof window !== "undefined" ? window.innerHeight : 1080
  );

  // Form states for different tabs
  const [newMedication, setNewMedication] = useState({
    name: "",
    dosage: "",
    frequency: "",
    effect: "",
  });
  const [showMedicationForm, setShowMedicationForm] = useState(false);

  useEffect(() => {
    if (isOpen && data && !hasInitialized) {
      setIsVisible(true);
      const initialData = {
        ...data,
        narrative_summary: data.narrative_summary || "",
        medications: data.medications || [],
        therapeutic_highlights: data.therapeutic_highlights || "",
        timeline: data.timeline || [], // Initialize timeline
        last_updated: data.last_updated || new Date().toISOString(),
      };
      setEditData(initialData);
      setHasInitialized(true);
      setIsAnimating(true);
      if (onAnimationStart) onAnimationStart();

      setTimeout(() => {
        setIsAnimating(false);
        if (onAnimationEnd) onAnimationEnd();
      }, 600);
    } else if (!isOpen && hasInitialized) {
      setHasInitialized(false);
      setScrollPositions({});
      setEditingSections({});
      setSectionData({});
    }
  }, [isOpen, data, hasInitialized, onAnimationStart, onAnimationEnd]);

  // Enhanced effect for instant feedback - updates editData immediately when data changes
  useEffect(() => {
    if (isOpen && data && hasInitialized) {
      // Update editData with latest data for instant feedback
      setEditData((prevEditData) => {
        const updatedData = {
          ...prevEditData, // Keep any local edits
          ...data, // Override with latest data from parent
        };
        return updatedData;
      });
    }
  }, [data, isOpen, hasInitialized]);

  const handleClose = useCallback(() => {
    if (isAnimating || isClosing) return;

    setIsAnimating(true);
    setIsClosing(true);
    if (onAnimationStart) onAnimationStart();

    // Set visibility to false to trigger exit animation
    setIsVisible(false);
  }, [onAnimationStart, isAnimating, isClosing]);

  // Escape key handling to close modal - MOVED AFTER handleClose definition
  useEffect(() => {
    const handleKeyDown = (event) => {
      if (event.key === "Escape") {
        handleClose();
      }
    };

    if (isOpen) {
      document.addEventListener("keydown", handleKeyDown);
      return () => {
        document.removeEventListener("keydown", handleKeyDown);
      };
    }
  }, [isOpen, handleClose]);

  const handleSave = useCallback(async () => {
    if (isLoading) return;

    setIsLoading(true);
    try {
      const updatedData = {
        ...editData,
        last_updated: new Date().toISOString(),
      };

      setMindMapData((prevData) => {
        const updatedCases = prevData.cases.map((caseItem) =>
          String(caseItem.id) === String(data?.id)
            ? { ...caseItem, ...updatedData }
            : caseItem
        );
        const newData = { ...prevData, cases: updatedCases };
        autoSaveMindMapData(newData);
        return newData;
      });

      setEditData(updatedData);
      addToast("Case updated successfully", "success");
    } catch (error) {
      console.error("Error saving case:", error);
      addToast("Failed to save case", "error");
    } finally {
      setIsLoading(false);
    }
  }, [
    data?.id,
    editData,
    setMindMapData,
    autoSaveMindMapData,
    addToast,
    isLoading,
  ]);

  // Save current tab's scroll position before switching
  const saveScrollPosition = useCallback((tabId) => {
    const contentRef = contentRefs.current[tabId];
    if (contentRef) {
      setScrollPositions((prev) => ({
        ...prev,
        [tabId]: contentRef.scrollTop,
      }));
    }
  }, []);

  // Restore scroll position when switching to a tab
  const restoreScrollPosition = useCallback(
    (tabId) => {
      setTimeout(() => {
        const contentRef = contentRefs.current[tabId];
        const savedPosition = scrollPositions[tabId];
        if (contentRef && savedPosition) {
          contentRef.scrollTop = savedPosition;
        }
      }, 100); // Small delay to ensure content is rendered
    },
    [scrollPositions]
  );

  // Handle tab switching with scroll position preservation
  const handleTabSwitch = useCallback(
    (newTabId) => {
      if (newTabId === activeTab || isTabTransitioning) return;

      // Save current tab's scroll position
      saveScrollPosition(activeTab);
      // Capture current panel height before switching to animate from
      const currentEl = contentRefs.current[activeTab];
      if (contentWrapperRef.current) {
        // Prefer actual rendered wrapper height as the starting point
        setContentHeight(contentWrapperRef.current.offsetHeight);
      } else if (currentEl) {
        // Fallback to panel height if wrapper not yet available
        setContentHeight(currentEl.scrollHeight);
      }

      setIsTabTransitioning(true);
      setActiveTab(newTabId);

      setTimeout(() => {
        setIsTabTransitioning(false);
        // Restore new tab's scroll position
        restoreScrollPosition(newTabId);
      }, 300);
    },
    [activeTab, isTabTransitioning, saveScrollPosition, restoreScrollPosition]
  );

  // Helper: compute max modal and target wrapper height (clamped to viewport)
  const computeTargetHeight = useCallback((panelEl) => {
    const headerH = headerRef.current?.offsetHeight || 0;
    const tabsH = tabsRef.current?.offsetHeight || 0;
    const chrome = headerH + tabsH;
    const maxModalH = Math.round(
      (viewportHRef.current || window.innerHeight || 1080) * 0.9
    ); // matches max-h-[90vh]
    const maxWrapperH = Math.max(160, maxModalH - chrome);
    // Prefer the largest among layout and visual box to avoid under-measure during transforms
    const rectH = panelEl?.getBoundingClientRect
      ? Math.ceil(panelEl.getBoundingClientRect().height)
      : 0;
    const offsetH = panelEl?.offsetHeight || 0;
    const scrollH = panelEl?.scrollHeight || 0;
    const panelH = Math.max(rectH, offsetH, scrollH);
    return Math.min(panelH || 0, maxWrapperH);
  }, []);

  // Measure helper to update height immediately when a panel mounts
  const measureNow = useCallback(
    (panelEl) => {
      if (!panelEl) return;
      viewportHRef.current =
        typeof window !== "undefined"
          ? window.innerHeight
          : viewportHRef.current;
      setContentHeight(computeTargetHeight(panelEl));
    },
    [computeTargetHeight]
  );

  // On first open, measure after layout and once more on next frame to avoid transform-induced undershoot
  useLayoutEffect(() => {
    if (!hasInitialized) return;
    const el = contentRefs.current[activeTab];
    if (!el) return;
    let f1 = requestAnimationFrame(() => {
      setContentHeight(computeTargetHeight(el));
      // measure one more time next frame
      f1 = requestAnimationFrame(() =>
        setContentHeight(computeTargetHeight(el))
      );
    });
    return () => cancelAnimationFrame(f1);
  }, [hasInitialized, activeTab, computeTargetHeight]);

  // Ensure we measure once the modal has initialized and the first panel is in the DOM
  useEffect(() => {
    if (!hasInitialized) return;
    const raf = requestAnimationFrame(() => {
      const el = contentRefs.current[activeTab];
      if (el) measureNow(el);
    });
    return () => cancelAnimationFrame(raf);
  }, [hasInitialized, activeTab, measureNow]);

  // Update contentHeight when active tab content renders/changes and on resize
  useEffect(() => {
    const nextEl = contentRefs.current[activeTab];
    if (!nextEl) return;

    const update = () => {
      // Keep viewport height up to date
      viewportHRef.current =
        typeof window !== "undefined"
          ? window.innerHeight
          : viewportHRef.current;
      setContentHeight(computeTargetHeight(nextEl));
    };

    // Initial measure after paint
    const raf = requestAnimationFrame(update);
    // Observe size changes while mounted
    const ro = new ResizeObserver(update);
    ro.observe(nextEl);
    // Listen to viewport resizes
    const onResize = () => update();
    window.addEventListener("resize", onResize);
    return () => {
      cancelAnimationFrame(raf);
      try {
        ro.disconnect();
      } catch {}
      window.removeEventListener("resize", onResize);
    };
  }, [activeTab, computeTargetHeight]);

  // Section editing functionality
  const toggleEditSection = useCallback(
    (sectionId) => {
      setEditingSections((prev) => ({
        ...prev,
        [sectionId]: !prev[sectionId],
      }));

      // Initialize section data if starting to edit
      if (!editingSections[sectionId]) {
        setSectionData((prev) => ({
          ...prev,
          [sectionId]: {
            // Initialize with current values from editData
            ...(sectionId === "basic_info" && {
              label: editData.label || editData.title || "",
              status: editData.status || "active",
            }),
            ...(sectionId === "chief_complaint" && {
              content:
                editData.chiefComplaint || editData.chief_complaint || "",
            }),
            ...(sectionId === "initial_presentation" && {
              content:
                editData.initialPresentation ||
                editData.initial_presentation ||
                "",
            }),
            ...(sectionId === "narrative" && {
              content: editData.narrative_summary || "",
            }),
            ...(sectionId === "therapeutic_highlights" && {
              therapeutic_highlights: editData.therapeutic_highlights || "",
            }),
          },
        }));
      }
    },
    [editingSections, editData]
  );

  const updateSectionData = useCallback((sectionId, field, value) => {
    // Update sectionData for temporary editing state
    setSectionData((prev) => ({
      ...prev,
      [sectionId]: {
        ...prev[sectionId],
        [field]: value,
      },
    }));
  }, []);

  const cancelEdit = useCallback((sectionId) => {
    setEditingSections((prev) => ({
      ...prev,
      [sectionId]: false,
    }));
    setSectionData((prev) => {
      const newData = { ...prev };
      delete newData[sectionId];
      return newData;
    });
  }, []);

  const saveSection = useCallback(
    async (sectionId) => {
      if (isLoading) return;

      setIsLoading(true);
      try {
        const sectionChanges = sectionData[sectionId] || {};
        let updatedData = { ...editData };

        // Apply section-specific changes
        if (sectionId === "basic_info") {
          if (sectionChanges.label) {
            updatedData.label = sectionChanges.label;
            updatedData.title = sectionChanges.label; // Also update title for compatibility
          }
          if (sectionChanges.status) {
            updatedData.status = sectionChanges.status;
          }
        } else if (sectionId === "chief_complaint") {
          if (sectionChanges.content !== undefined) {
            updatedData.chief_complaint = sectionChanges.content;
            updatedData.chiefComplaint = sectionChanges.content;
          }
        } else if (sectionId === "initial_presentation") {
          if (sectionChanges.content !== undefined) {
            updatedData.initial_presentation = sectionChanges.content;
            updatedData.initialPresentation = sectionChanges.content;
          }
        } else if (sectionId === "narrative") {
          if (sectionChanges.content !== undefined) {
            updatedData.narrative_summary = sectionChanges.content;
          }
        }

        updatedData.last_updated = new Date().toISOString();

        // Update editData immediately for instant feedback
        setEditData(updatedData);

        // Update parent data
        setMindMapData((prevData) => {
          const updatedCases = prevData.cases.map((caseItem) =>
            String(caseItem.id) === String(data?.id)
              ? { ...caseItem, ...updatedData }
              : caseItem
          );
          const newData = { ...prevData, cases: updatedCases };
          autoSaveMindMapData(newData);
          return newData;
        });

        // Clear editing state
        setEditingSections((prev) => ({
          ...prev,
          [sectionId]: false,
        }));
        setSectionData((prev) => {
          const newData = { ...prev };
          delete newData[sectionId];
          return newData;
        });

        addToast("Case information updated successfully", "success");
      } catch (error) {
        console.error("Error saving section:", error);
        addToast("Failed to save changes", "error");
      } finally {
        setIsLoading(false);
      }
    },
    [
      sectionData,
      editData,
      data?.id,
      setMindMapData,
      autoSaveMindMapData,
      addToast,
      isLoading,
    ]
  );

  const handleDelete = useCallback(async () => {
    if (isLoading) return;

    if (!window.confirm("Are you sure you want to delete this case?")) return;

    setIsLoading(true);
    try {
      setMindMapData((prevData) => {
        const updatedCases = prevData.cases.filter(
          (caseItem) => String(caseItem.id) !== String(data?.id)
        );
        const newData = { ...prevData, cases: updatedCases };
        autoSaveMindMapData(newData);
        return newData;
      });

      addToast("Case deleted successfully", "success");
      handleClose();
    } catch (error) {
      console.error("Error deleting case:", error);
      addToast("Failed to delete case", "error");
    } finally {
      setIsLoading(false);
    }
  }, [
    data?.id,
    setMindMapData,
    autoSaveMindMapData,
    addToast,
    handleClose,
    isLoading,
  ]);

  // Individual section edit functions
  const startEditingSection = useCallback(
    (sectionId) => {
      setEditingSections((prev) => ({ ...prev, [sectionId]: true }));
      // Initialize section data with current values
      setSectionData((prev) => ({
        ...prev,
        [sectionId]: { ...editData },
      }));
    },
    [editData]
  );

  const cancelEditingSection = useCallback((sectionId) => {
    setEditingSections((prev) => ({ ...prev, [sectionId]: false }));
    setSectionData((prev) => {
      const newData = { ...prev };
      delete newData[sectionId];
      return newData;
    });
  }, []);

  const saveSectionEdit = useCallback(
    async (sectionId) => {
      if (isLoading) return;

      const sectionChanges = sectionData[sectionId];
      if (!sectionChanges) return;

      setIsLoading(true);
      try {
        const updatedData = {
          ...editData,
          ...sectionChanges,
          last_updated: new Date().toISOString(),
        };

        // Update editData immediately for instant feedback
        setEditData(updatedData);

        setMindMapData((prevData) => {
          const updatedCases = prevData.cases.map((caseItem) =>
            String(caseItem.id) === String(data?.id)
              ? { ...caseItem, ...updatedData }
              : caseItem
          );
          const newData = { ...prevData, cases: updatedCases };
          autoSaveMindMapData(newData);
          return newData;
        });

        setEditingSections((prev) => ({ ...prev, [sectionId]: false }));
        setSectionData((prev) => {
          const newData = { ...prev };
          delete newData[sectionId];
          return newData;
        });

        addToast("Section updated successfully", "success");
      } catch (error) {
        console.error("Error saving section:", error);
        addToast("Failed to save section", "error");
      } finally {
        setIsLoading(false);
      }
    },
    [
      sectionData,
      editData,
      data?.id,
      setMindMapData,
      autoSaveMindMapData,
      addToast,
      isLoading,
    ]
  );

  const updateSectionField = useCallback((sectionId, field, value) => {
    setSectionData((prev) => ({
      ...prev,
      [sectionId]: {
        ...prev[sectionId],
        [field]: value,
      },
    }));
  }, []);

  // Medication management functions
  const addMedication = useCallback(() => {
    if (!newMedication.name.trim()) return;

    const updatedMedications = [
      ...(editData.medications || []),
      {
        id: Date.now(),
        ...newMedication,
        dateAdded: new Date().toISOString(),
      },
    ];

    const updatedData = {
      ...editData,
      medications: updatedMedications,
      last_updated: new Date().toISOString(),
    };

    setEditData(updatedData);

    setMindMapData((prevData) => {
      const updatedCases = prevData.cases.map((caseItem) =>
        String(caseItem.id) === String(data?.id)
          ? { ...caseItem, ...updatedData }
          : caseItem
      );
      const newData = { ...prevData, cases: updatedCases };
      autoSaveMindMapData(newData);
      return newData;
    });

    setNewMedication({ name: "", dosage: "", frequency: "", effect: "" });
    setShowMedicationForm(false);
    addToast("Medication added successfully", "success");
  }, [
    newMedication,
    editData,
    data?.id,
    setMindMapData,
    autoSaveMindMapData,
    addToast,
  ]);

  const removeMedication = useCallback(
    (medicationId) => {
      const updatedMedications = (editData.medications || []).filter(
        (med) => med.id !== medicationId
      );
      const updatedData = {
        ...editData,
        medications: updatedMedications,
        last_updated: new Date().toISOString(),
      };

      setEditData(updatedData);

      setMindMapData((prevData) => {
        const updatedCases = prevData.cases.map((caseItem) =>
          String(caseItem.id) === String(data?.id)
            ? { ...caseItem, ...updatedData }
            : caseItem
        );
        const newData = { ...prevData, cases: updatedCases };
        autoSaveMindMapData(newData);
        return newData;
      });

      addToast("Medication removed successfully", "success");
    },
    [editData, data?.id, setMindMapData, autoSaveMindMapData, addToast]
  );

  // Enhanced timeline management with debounced auto-save and better backend integration
  const timelineEntries = useMemo(() => {
    // Only process timeline when timeline tab is active to improve initial render performance
    if (activeTab !== 'timeline') return [];
    // Ensure timeline data is properly structured for the VerticalTimeline component
    const timeline = editData.timeline || [];
    console.log(`Timeline entries for case ${data?.id}:`, timeline);
    return timeline;
  }, [editData.timeline, data?.id, activeTab]);

  // Debounced timeline save function with enhanced error handling
  const debouncedTimelineSave = useCallback(
    debounce(async (updatedTimeline, retryCount = 0) => {
      try {
        // Validate timeline data structure
        const validatedTimeline = updatedTimeline.map((entry, index) => ({
          id: entry.id || `timeline-${data?.id}-${Date.now()}-${index}`,
          title: entry.title || `Timeline Entry ${index + 1}`,
          type: entry.type || "timeline_entry",
          timestamp: entry.timestamp || entry.date || new Date().toISOString(),
          date: entry.date || entry.timestamp || new Date().toISOString(),
          patient_narrative:
            entry.patient_narrative || entry.patientData?.notes || "",
          clinical_notes:
            entry.clinical_notes || entry.clinicalData?.notes || "",
          content:
            entry.content ||
            entry.patient_narrative ||
            entry.clinical_notes ||
            "",
          symptoms: entry.symptoms || [],
          orderIndex: entry.orderIndex !== undefined ? entry.orderIndex : index,
          x: entry.x || 400, // Default center position
          y: entry.y || 100 + index * 200, // Default spacing
          created_at: entry.created_at || new Date().toISOString(),
          updated_at: new Date().toISOString(),
          // Keep original data for backward compatibility
          ...entry,
        }));

        const updatedData = {
          ...editData,
          timeline: validatedTimeline,
          last_updated: new Date().toISOString(),
        };

        // Update editData immediately for instant feedback
        setEditData(updatedData);

        // Enhanced mind map data update with better timeline integration
        setMindMapData((prevData) => {
          const updatedCases = prevData.cases.map((caseItem) => {
            if (String(caseItem.id) === String(data?.id)) {
              return {
                ...caseItem,
                ...updatedData,
                // Ensure timeline data is properly structured for backend
                timeline: validatedTimeline.map((entry) => ({
                  id: String(
                    entry.id ||
                      `${Date.now()}-${caseItem.id}-timeline-${
                        entry.orderIndex || 0
                      }`
                  ),
                  title:
                    entry.title ||
                    `Timeline Entry ${(entry.orderIndex || 0) + 1}`,
                  type: entry.type || "timeline_entry",
                  timestamp:
                    entry.timestamp || entry.date || new Date().toISOString(),
                  date:
                    entry.date || entry.timestamp || new Date().toISOString(),
                  patient_narrative: entry.patient_narrative || "",
                  clinical_notes: entry.clinical_notes || "",
                  content:
                    entry.content ||
                    entry.patient_narrative ||
                    entry.clinical_notes ||
                    "",
                  symptoms: entry.symptoms || [],
                  orderIndex:
                    entry.orderIndex !== undefined ? entry.orderIndex : 0,
                  x: Number(entry.x) || 400,
                  y: Number(entry.y) || 100,
                  created_at: entry.created_at || new Date().toISOString(),
                  updated_at: new Date().toISOString(),
                })),
              };
            }
            return caseItem;
          });
          const newData = { ...prevData, cases: updatedCases };
          autoSaveMindMapData(newData);
          return newData;
        });

        return { success: true, data: updatedData };
      } catch (error) {
        console.error("Timeline save error:", error);

        // Retry logic - up to 3 attempts
        if (retryCount < 3) {
          console.log(`Retrying timeline save (attempt ${retryCount + 1}/3)`);
          return debouncedTimelineSave(updatedTimeline, retryCount + 1);
        }

        return { success: false, error };
      }
    }, 500), // 500ms debounce
    [editData, data?.id, setMindMapData, autoSaveMindMapData]
  );

  const updateTimeline = useCallback(
    async (updatedTimeline, options = {}) => {
      if (isLoading && !options.force) return;

      // Enhanced validation - check for meaningful content or position changes
      const hasContent = updatedTimeline.some(
        (entry) =>
          (entry.patient_narrative && entry.patient_narrative.trim()) ||
          (entry.clinical_notes && entry.clinical_notes.trim()) ||
          (entry.content && entry.content.trim()) ||
          entry.x !== 400 ||
          entry.y !== 100 // Position has changed from default
      );

      // Always save if forced or if there's meaningful content/changes
      if (!hasContent && !options.force) {
        console.log(
          "Skipping timeline save - no meaningful content or changes"
        );
        return { success: true, skipped: true };
      }

      console.log(
        `Updating timeline for case ${data?.id} with ${updatedTimeline.length} entries`
      );
      return debouncedTimelineSave(updatedTimeline);
    },
    [debouncedTimelineSave, isLoading, data?.id]
  );

  // Get connected nodes for Related tab
  const connectedNodes = useMemo(() => {
    if (!data?.id || !connections.length || !allNodes.length) {
      return { topics: [], literature: [], tasks: [], cases: [] };
    }

    const currentNodeId = `case-${data.id}`;
    
    // Find all connections where this case is involved
    const relatedConnections = connections.filter(
      conn => conn.source === currentNodeId || conn.target === currentNodeId
    );

    // Get IDs of connected nodes
    const connectedNodeIds = relatedConnections.map(conn => 
      conn.source === currentNodeId ? conn.target : conn.source
    );

    // Group connected nodes by type
    const grouped = {
      topics: [],
      literature: [],
      tasks: [],
      cases: []
    };

    connectedNodeIds.forEach(nodeId => {
      const nodeWrapper = allNodes.find(n => n.id === nodeId);
      
      if (!nodeWrapper || !nodeWrapper.data) {
        return;
      }

      const nodeData = nodeWrapper.data;
      const nodeType = nodeWrapper.type;

      // Add to appropriate group based on type and ensure required fields exist
      if (nodeType === 'topic' && (nodeData.title || nodeData.label)) {
        grouped.topics.push(nodeData);
      } else if (nodeType === 'literature' && (nodeData.title || nodeData.label)) {
        grouped.literature.push(nodeData);
      } else if (nodeType === 'task' && (nodeData.title || nodeData.label || nodeData.description)) {
        grouped.tasks.push(nodeData);
      } else if (nodeType === 'case' && (nodeData.case_id || nodeData.primary_diagnosis || nodeData.title)) {
        grouped.cases.push(nodeData);
      }
    });

    return grouped;
  }, [data?.id, connections, allNodes]);

  // Tab configuration
  const tabs = [
    { id: "overview", label: "Overview", icon: Users },
    { id: "medications", label: "Medications", icon: Pill },
    { id: "therapy", label: "Therapy & Insights", icon: Brain },
    { id: "timeline", label: "Timeline", icon: Clock },
    { id: "related", label: "Related", icon: Link2 },
  ];

  if (!isOpen) return null;

  return (
    <AnimatePresence
      mode="wait"
      onExitComplete={() => {
        setIsAnimating(false);
        setIsClosing(false);
        setHasInitialized(false);
        onClose();
        if (onAnimationEnd) onAnimationEnd();
      }}
    >
      {isVisible && (
        <motion.div
          key={`case-modal-${data?.id || "default"}`}
          initial="hidden"
          animate="visible"
          exit="exit"
          variants={backdropVariants}
          className="fixed inset-0 bg-black flex items-center justify-center z-50"
          style={{
            willChange: "backdrop-filter, opacity",
            backfaceVisibility: "hidden",
            transform: "translate3d(0, 0, 0)",
          }}
          onClick={(e) => e.target === e.currentTarget && handleClose()}
        >
          <motion.div
            initial="hidden"
            animate="visible"
            exit="exit"
            variants={modalVariants}
            className={`bg-white rounded-2xl shadow-2xl w-full mx-4 max-h-[90vh] overflow-hidden ${
              activeTab === "timeline" ? "max-w-7xl" : "max-w-4xl"
            }`}
            style={{
              willChange: "transform, opacity",
              backfaceVisibility: "hidden",
            }}
            onClick={(e) => e.stopPropagation()}
            onAnimationStart={() => {
              setIsAnimating(true);
              if (onAnimationStart) onAnimationStart();
            }}
            onAnimationComplete={() => {
              setIsAnimating(false);
              if (onAnimationEnd) onAnimationEnd();
            }}
          >
            <motion.div
              ref={headerRef}
              initial="hidden"
              animate="visible"
              exit="exit"
              variants={contentVariants}
              className="bg-gradient-to-br from-slate-900 to-slate-800 text-white px-6 py-4 flex items-center justify-between"
            >
              <div className="flex items-center gap-3">
                <Users size={24} />
                <h2 className="text-xl font-semibold">Case Details</h2>
              </div>
              <button
                onClick={handleClose}
                className="text-slate-400 hover:text-white transition-colors"
              >
                <X size={24} />
              </button>
            </motion.div>

            {/* Tab Navigation */}
            <div
              ref={tabsRef}
              className="bg-gradient-to-r from-slate-900 via-slate-800 to-slate-900 border-b border-slate-600"
            >
              <nav className="flex flex-wrap gap-2 px-6 py-4">
                {tabs.map(({ id, label, icon: Icon }) => (
                  <motion.button
                    key={id}
                    onClick={() => handleTabSwitch(id)}
                    className={`relative flex items-center gap-2 px-4 py-3 rounded-xl font-medium text-sm transition-all duration-300 ${
                      activeTab === id
                        ? "bg-gradient-to-r from-indigo-500 to-indigo-600 text-white shadow-lg shadow-indigo-500/25"
                        : "text-slate-300 hover:text-white hover:bg-slate-700/50 hover:shadow-md"
                    }`}
                    whileHover={{ scale: activeTab === id ? 1 : 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    disabled={isTabTransitioning}
                  >
                    <Icon
                      size={16}
                      className={activeTab === id ? "drop-shadow-sm" : ""}
                    />
                    {label}

                    {activeTab === id && (
                      <motion.div
                        layoutId="caseActiveTab"
                        className="absolute inset-0 bg-gradient-to-r from-indigo-400/20 to-indigo-500/20 rounded-xl blur-sm"
                        initial={false}
                        transition={{ duration: 0.3, ease: "easeOut" }}
                      />
                    )}
                  </motion.button>
                ))}
              </nav>
            </div>

            {/* Dark Content Area */}
            <motion.div
              ref={contentWrapperRef}
              className="bg-gradient-to-br from-slate-900 to-slate-800 overflow-y-auto overflow-x-hidden"
              initial={false}
              animate={{ height: contentHeight }}
              style={{ willChange: "height" }}
              transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
            >
              <AnimatePresence mode="wait">
                {/* Overview Tab */}
                {activeTab === "overview" && (
                  <motion.div
                    layout
                    key="overview"
                    ref={(el) => {
                      contentRefs.current.overview = el;
                      if (el && activeTab === "overview") measureNow(el);
                    }}
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: 20 }}
                    transition={{ duration: 0.3 }}
                    className="p-6 space-y-6"
                  >
                    {/* Case Title and Basic Info */}
                    <motion.div
                      variants={cardVariants}
                      initial="hidden"
                      animate="visible"
                      className="bg-slate-800/50 backdrop-blur-sm rounded-xl p-6 border border-slate-700"
                    >
                      <div className="flex items-center justify-between mb-4">
                        <h3 className="text-lg font-semibold text-white">
                          Case Information
                        </h3>
                        <motion.button
                          whileHover={{ scale: 1.05 }}
                          whileTap={{ scale: 0.95 }}
                          onClick={() => toggleEditSection("basic_info")}
                          className="text-blue-400 hover:text-blue-300 transition-colors p-2 rounded-lg hover:bg-slate-700/50"
                          title="Edit case information"
                        >
                          <Edit3 size={16} />
                        </motion.button>
                      </div>

                      {editingSections.basic_info ? (
                        <div className="space-y-4">
                          <div className="grid md:grid-cols-2 gap-4">
                            <div>
                              <label className="block text-sm font-medium text-slate-300 mb-2">
                                Name or ID
                              </label>
                              <input
                                type="text"
                                value={
                                  sectionData.basic_info?.label !== undefined
                                    ? sectionData.basic_info.label
                                    : editData.label || editData.title || ""
                                }
                                onChange={(e) =>
                                  updateSectionData(
                                    "basic_info",
                                    "label",
                                    e.target.value
                                  )
                                }
                                className="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-2 text-white placeholder-slate-400 focus:ring-2 focus:ring-blue-400 focus:border-blue-400"
                                placeholder="Enter patient name or case ID"
                              />
                            </div>
                            <div>
                              <label className="block text-sm font-medium text-slate-300 mb-2">
                                Status
                              </label>
                              <select
                                value={
                                  sectionData.basic_info?.status !== undefined
                                    ? sectionData.basic_info.status
                                    : editData.status || "active"
                                }
                                onChange={(e) =>
                                  updateSectionData(
                                    "basic_info",
                                    "status",
                                    e.target.value
                                  )
                                }
                                className="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-400 focus:border-blue-400"
                              >
                                <option value="active">Active</option>
                                <option value="archived">Archived</option>
                                <option value="follow_up">Follow-up</option>
                                <option value="completed">Completed</option>
                              </select>
                            </div>
                          </div>

                          {/* Action buttons area - consistent height */}
                          <div className="flex gap-2 justify-end min-h-[44px] items-center">
                            <motion.button
                              whileHover={{ scale: 1.05 }}
                              whileTap={{ scale: 0.95 }}
                              onClick={() => cancelEdit("basic_info")}
                              className="px-4 py-2 bg-slate-600 text-white rounded-lg hover:bg-slate-500 transition-colors"
                            >
                              Cancel
                            </motion.button>
                            <motion.button
                              whileHover={{ scale: 1.05 }}
                              whileTap={{ scale: 0.95 }}
                              onClick={() => saveSection("basic_info")}
                              className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors flex items-center gap-2"
                            >
                              <Save size={16} />
                              Save Changes
                            </motion.button>
                          </div>
                        </div>
                      ) : (
                        <div className="space-y-4">
                          <div className="grid md:grid-cols-2 gap-4">
                            <div>
                              <label className="block text-sm font-medium text-slate-300 mb-2">
                                Name or ID
                              </label>
                              <div
                                className={`bg-slate-700/50 rounded-lg p-3 ${
                                  editData.label || editData.title
                                    ? "text-white"
                                    : "text-slate-400 italic"
                                }`}
                              >
                                {editData.label ||
                                  editData.title ||
                                  "Unnamed patient"}
                              </div>
                            </div>
                            <div>
                              <label className="block text-sm font-medium text-slate-300 mb-2">
                                Status
                              </label>
                              <div className="text-white bg-slate-700/50 rounded-lg p-3">
                                {editData.status || "Active"}
                              </div>
                            </div>
                          </div>

                          {/* Reserved space for action buttons - maintains consistent height */}
                          <div className="flex gap-2 justify-end min-h-[44px] items-center">
                            {/* Empty space to maintain layout consistency */}
                          </div>
                        </div>
                      )}
                    </motion.div>

                    {/* Narrative Summary */}
                    <motion.div
                      variants={cardVariants}
                      initial="hidden"
                      animate="visible"
                      className="bg-slate-800/50 backdrop-blur-sm rounded-xl p-6 border border-slate-700"
                    >
                      <div className="flex items-center justify-between mb-4">
                        <h3 className="text-lg font-semibold text-white flex items-center gap-2">
                          <FileText size={20} className="text-blue-400" />
                          Case Narrative
                        </h3>
                        <motion.button
                          whileHover={{ scale: 1.05 }}
                          whileTap={{ scale: 0.95 }}
                          onClick={() => toggleEditSection("narrative")}
                          className="text-blue-400 hover:text-blue-300 transition-colors p-2 rounded-lg hover:bg-slate-700/50"
                          title="Edit narrative summary"
                        >
                          <Edit3 size={16} />
                        </motion.button>
                      </div>

                      {editingSections.narrative ? (
                        <div className="space-y-4">
                          <textarea
                            value={
                              sectionData.narrative?.content !== undefined
                                ? sectionData.narrative.content
                                : editData.narrative_summary || ""
                            }
                            onChange={(e) =>
                              updateSectionData(
                                "narrative",
                                "content",
                                e.target.value
                              )
                            }
                            rows={8}
                            className="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-2 text-white placeholder-slate-400 focus:ring-2 focus:ring-blue-400 focus:border-blue-400 resize-none"
                            placeholder="Enter the narrative summary for this case..."
                          />

                          {/* Action buttons area - consistent height */}
                          <div className="flex gap-2 justify-end min-h-[44px] items-center">
                            <motion.button
                              whileHover={{ scale: 1.05 }}
                              whileTap={{ scale: 0.95 }}
                              onClick={() => cancelEdit("narrative")}
                              className="px-4 py-2 bg-slate-600 text-white rounded-lg hover:bg-slate-500 transition-colors"
                            >
                              Cancel
                            </motion.button>
                            <motion.button
                              whileHover={{ scale: 1.05 }}
                              whileTap={{ scale: 0.95 }}
                              onClick={() => saveSection("narrative")}
                              className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors flex items-center gap-2"
                            >
                              <Save size={16} />
                              Save Changes
                            </motion.button>
                          </div>
                        </div>
                      ) : (
                        <div className="space-y-4">
                          <div
                            className={`leading-relaxed bg-slate-700/30 rounded-lg p-4 ${
                              editData.narrative_summary
                                ? "text-slate-300"
                                : "text-slate-400 italic"
                            }`}
                          >
                            {editData.narrative_summary ||
                              "No narrative summary documented"}
                          </div>

                          {/* Reserved space for action buttons - maintains consistent height */}
                          <div className="flex gap-2 justify-end min-h-[44px] items-center">
                            {/* Empty space to maintain layout consistency */}
                          </div>
                        </div>
                      )}
                    </motion.div>

                    {/* Last Updated */}
                    <div className="text-xs text-slate-500 text-right">
                      Last updated:{" "}
                      {editData.last_updated
                        ? new Date(editData.last_updated).toLocaleString()
                        : "Never"}
                    </div>
                  </motion.div>
                )}

                {/* Medications Tab */}
                {activeTab === "medications" && (
                  <motion.div
                    layout
                    key="medications"
                    ref={(el) => {
                      contentRefs.current.medications = el;
                      if (el && activeTab === "medications") measureNow(el);
                    }}
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: 20 }}
                    transition={{ duration: 0.3 }}
                    className="p-6 space-y-6"
                  >
                    {/* Medications List */}
                    <motion.div
                      variants={cardVariants}
                      initial="hidden"
                      animate="visible"
                      className="bg-slate-800/50 backdrop-blur-sm rounded-xl p-6 border border-slate-700"
                    >
                      <h3 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
                        <Pill size={20} className="text-green-400" />
                        Current Medications
                      </h3>

                      {/* Existing Medications */}
                      <div className="space-y-4 mb-6">
                        <AnimatePresence>
                          {(editData.medications || []).map(
                            (medication, index) => (
                              <motion.div
                                key={medication.id || index}
                                initial={{ opacity: 0, scale: 0.8 }}
                                animate={{ opacity: 1, scale: 1 }}
                                exit={{ opacity: 0, scale: 0.8 }}
                                className="bg-green-600/10 border border-green-600/20 rounded-lg p-4 group hover:bg-green-600/15 transition-colors"
                              >
                                <div className="flex items-start justify-between">
                                  <div className="flex-1">
                                    <div className="flex items-center gap-3 mb-2">
                                      <h4 className="font-semibold text-green-300">
                                        {medication.name}
                                      </h4>
                                      {medication.dosage && (
                                        <span className="text-xs bg-green-600/20 text-green-300 px-2 py-1 rounded">
                                          {medication.dosage}
                                        </span>
                                      )}
                                    </div>
                                    <div className="space-y-1 text-sm text-slate-300">
                                      {medication.frequency && (
                                        <div className="flex items-center gap-2">
                                          <Clock
                                            size={14}
                                            className="text-green-400"
                                          />
                                          <span>
                                            Frequency: {medication.frequency}
                                          </span>
                                        </div>
                                      )}
                                      {medication.effect && (
                                        <div className="flex items-center gap-2">
                                          <Activity
                                            size={14}
                                            className="text-green-400"
                                          />
                                          <span>
                                            Effect: {medication.effect}
                                          </span>
                                        </div>
                                      )}
                                      {medication.dateAdded && (
                                        <div className="flex items-center gap-2">
                                          <Calendar
                                            size={14}
                                            className="text-green-400"
                                          />
                                          <span>
                                            Added:{" "}
                                            {new Date(
                                              medication.dateAdded
                                            ).toLocaleDateString()}
                                          </span>
                                        </div>
                                      )}
                                    </div>
                                  </div>
                                  <motion.button
                                    whileHover={{ scale: 1.1 }}
                                    whileTap={{ scale: 0.9 }}
                                    onClick={() =>
                                      removeMedication(medication.id)
                                    }
                                    className="text-green-400 hover:text-green-200 opacity-0 group-hover:opacity-100 transition-opacity p-1 rounded"
                                    title="Remove medication"
                                  >
                                    <Trash2 size={16} />
                                  </motion.button>
                                </div>
                              </motion.div>
                            )
                          )}
                        </AnimatePresence>
                      </div>

                      {/* Add New Medication */}
                      {!showMedicationForm ? (
                        <motion.button
                          whileHover={{ scale: 1.02 }}
                          whileTap={{ scale: 0.98 }}
                          onClick={() => setShowMedicationForm(true)}
                          className="w-full flex items-center justify-center gap-2 p-4 border-2 border-dashed border-green-600/30 rounded-lg text-green-400 hover:border-green-600/50 hover:bg-green-600/5 transition-colors"
                        >
                          <Plus size={16} />
                          Add New Medication
                        </motion.button>
                      ) : (
                        <motion.div
                          initial={{ opacity: 0, y: 20 }}
                          animate={{ opacity: 1, y: 0 }}
                          className="bg-slate-700/30 rounded-lg p-4 space-y-4"
                        >
                          <div className="grid md:grid-cols-2 gap-4">
                            <div>
                              <label className="block text-sm font-medium text-slate-300 mb-2">
                                Medication Name{" "}
                                <span className="text-red-400">*</span>
                              </label>
                              <input
                                type="text"
                                value={newMedication.name}
                                onChange={(e) =>
                                  setNewMedication((prev) => ({
                                    ...prev,
                                    name: e.target.value,
                                  }))
                                }
                                className="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-2 text-white placeholder-slate-400 focus:ring-2 focus:ring-green-500 focus:border-green-500"
                                placeholder="Enter medication name"
                              />
                            </div>
                            <div>
                              <label className="block text-sm font-medium text-slate-300 mb-2">
                                Dosage
                              </label>
                              <input
                                type="text"
                                value={newMedication.dosage}
                                onChange={(e) =>
                                  setNewMedication((prev) => ({
                                    ...prev,
                                    dosage: e.target.value,
                                  }))
                                }
                                className="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-2 text-white placeholder-slate-400 focus:ring-2 focus:ring-green-500 focus:border-green-500"
                                placeholder="e.g., 50mg"
                              />
                            </div>
                          </div>
                          <div className="grid md:grid-cols-2 gap-4">
                            <div>
                              <label className="block text-sm font-medium text-slate-300 mb-2">
                                Frequency
                              </label>
                              <input
                                type="text"
                                value={newMedication.frequency}
                                onChange={(e) =>
                                  setNewMedication((prev) => ({
                                    ...prev,
                                    frequency: e.target.value,
                                  }))
                                }
                                className="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-2 text-white placeholder-slate-400 focus:ring-2 focus:ring-green-500 focus:border-green-500"
                                placeholder="e.g., Once daily"
                              />
                            </div>
                            <div>
                              <label className="block text-sm font-medium text-slate-300 mb-2">
                                Effect/Notes
                              </label>
                              <input
                                type="text"
                                value={newMedication.effect}
                                onChange={(e) =>
                                  setNewMedication((prev) => ({
                                    ...prev,
                                    effect: e.target.value,
                                  }))
                                }
                                className="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-2 text-white placeholder-slate-400 focus:ring-2 focus:ring-green-500 focus:border-green-500"
                                placeholder="e.g., Improved mood"
                              />
                            </div>
                          </div>
                          <div className="flex justify-end gap-2">
                            <motion.button
                              whileHover={{ scale: 1.02 }}
                              whileTap={{ scale: 0.98 }}
                              onClick={() => {
                                setShowMedicationForm(false);
                                setNewMedication({
                                  name: "",
                                  dosage: "",
                                  frequency: "",
                                  effect: "",
                                });
                              }}
                              className="px-4 py-2 text-slate-300 hover:text-white border border-slate-600 rounded-lg hover:bg-slate-700 transition-colors"
                            >
                              Cancel
                            </motion.button>
                            <motion.button
                              whileHover={{ scale: 1.02 }}
                              whileTap={{ scale: 0.98 }}
                              onClick={addMedication}
                              disabled={!newMedication.name.trim()}
                              className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                              <Plus size={16} />
                              Add Medication
                            </motion.button>
                          </div>
                        </motion.div>
                      )}

                      {(editData.medications || []).length === 0 &&
                        !showMedicationForm && (
                          <p className="text-slate-500 italic text-center py-8">
                            No medications documented yet
                          </p>
                        )}
                    </motion.div>
                  </motion.div>
                )}

                {/* Therapy & Insights Tab */}
                {activeTab === "therapy" && (
                  <motion.div
                    layout
                    key="therapy"
                    ref={(el) => {
                      contentRefs.current.therapy = el;
                      if (el && activeTab === "therapy") measureNow(el);
                    }}
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: 20 }}
                    transition={{ duration: 0.3 }}
                    className="p-6 space-y-6"
                  >
                    {/* Therapeutic Highlights Section */}
                    <motion.div
                      variants={cardVariants}
                      animate={
                        editingSections.therapeutic_highlights
                          ? "edit"
                          : "visible"
                      }
                      className="bg-slate-800/50 backdrop-blur-sm rounded-xl p-6 border border-slate-700"
                    >
                      <div className="flex items-center justify-between mb-4">
                        <h3 className="text-lg font-semibold text-white flex items-center gap-2">
                          <Brain size={20} className="text-purple-400" />
                          Therapeutic Highlights
                        </h3>
                        {!editingSections.therapeutic_highlights && (
                          <motion.button
                            whileHover={{ scale: 1.1 }}
                            whileTap={{ scale: 0.9 }}
                            onClick={() =>
                              startEditingSection("therapeutic_highlights")
                            }
                            className="text-slate-400 hover:text-white transition-colors p-1 rounded"
                            title="Edit therapeutic highlights"
                          >
                            <Edit3 size={16} />
                          </motion.button>
                        )}
                      </div>

                      {editingSections.therapeutic_highlights ? (
                        <motion.div
                          className="space-y-4"
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ duration: 0.3 }}
                        >
                          <textarea
                            value={
                              sectionData.therapeutic_highlights
                                ?.therapeutic_highlights !== undefined
                                ? sectionData.therapeutic_highlights
                                    .therapeutic_highlights
                                : editData.therapeutic_highlights || ""
                            }
                            onChange={(e) =>
                              updateSectionField(
                                "therapeutic_highlights",
                                "therapeutic_highlights",
                                e.target.value
                              )
                            }
                            rows={10}
                            className="w-full bg-slate-700 border border-slate-600 rounded-lg px-4 py-3 text-white placeholder-slate-400 focus:ring-2 focus:ring-purple-500 focus:border-purple-500 resize-none"
                            placeholder="Enter key therapeutic moments, insights, breakthroughs, or notes on therapy process..."
                          />
                          <div className="flex justify-end gap-2">
                            <motion.button
                              whileHover={{ scale: 1.02 }}
                              whileTap={{ scale: 0.98 }}
                              onClick={() =>
                                cancelEditingSection("therapeutic_highlights")
                              }
                              className="px-3 py-2 text-slate-300 hover:text-white border border-slate-600 rounded-lg hover:bg-slate-700 transition-colors text-sm"
                            >
                              Cancel
                            </motion.button>
                            <motion.button
                              whileHover={{ scale: 1.02 }}
                              whileTap={{ scale: 0.98 }}
                              onClick={() =>
                                saveSectionEdit("therapeutic_highlights")
                              }
                              disabled={isLoading}
                              className="px-3 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-colors text-sm flex items-center gap-2"
                            >
                              {isLoading ? (
                                <Loader2 size={14} className="animate-spin" />
                              ) : (
                                <Save size={14} />
                              )}
                              Save
                            </motion.button>
                          </div>
                        </motion.div>
                      ) : (
                        <motion.div
                          className="text-slate-300 leading-relaxed cursor-pointer hover:bg-slate-700/20 rounded-lg p-4 transition-colors min-h-[200px]"
                          whileHover={{ scale: 1.01 }}
                          transition={{ duration: 0.2 }}
                          onClick={() =>
                            startEditingSection("therapeutic_highlights")
                          }
                        >
                          {editData.therapeutic_highlights ? (
                            <div className="whitespace-pre-wrap">
                              {editData.therapeutic_highlights}
                            </div>
                          ) : (
                            <span className="text-slate-500 italic">
                              Click to add therapeutic highlights, key moments,
                              insights, breakthroughs, or therapy process
                              notes...
                            </span>
                          )}
                        </motion.div>
                      )}
                    </motion.div>
                  </motion.div>
                )}

                {/* Timeline Tab */}
                {activeTab === "timeline" && (
                  <motion.div
                    layout
                    key="timeline"
                    ref={(el) => {
                      contentRefs.current.timeline = el;
                      if (el && activeTab === "timeline") measureNow(el);
                    }}
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: 20 }}
                    transition={{ duration: 0.3 }}
                    className=""
                  >
                    <VerticalTimeline
                      data={timelineEntries}
                      caseId={data?.id}
                      setMindMapData={setMindMapData}
                      autoSaveMindMapData={autoSaveMindMapData}
                      onDataChange={(timelineData) => {
                        // Handle timeline data changes - the VerticalTimeline handles the save internally
                        console.log("Timeline data updated:", timelineData);
                        addToast("Timeline updated successfully", "success");
                      }}
                    />
                  </motion.div>
                )}

                {/* Related Tab */}
                {activeTab === "related" && (
                  <motion.div
                    layout
                    key="related"
                    ref={(el) => {
                      contentRefs.current.related = el;
                      if (el && activeTab === "related") measureNow(el);
                    }}
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: 20 }}
                    transition={{ duration: 0.3 }}
                    className="p-6 space-y-6"
                  >
                    {/* Connected Nodes */}
                    <motion.div
                      variants={cardVariants}
                      initial="hidden"
                      animate="visible"
                      className="bg-slate-800/50 backdrop-blur-sm rounded-xl p-6 border border-slate-700"
                    >
                      <h3 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
                        <Link2 size={20} className="text-cyan-400" />
                        Connected Nodes
                        {(connectedNodes.topics.length + connectedNodes.literature.length + 
                          connectedNodes.tasks.length + connectedNodes.cases.length) > 0 && (
                          <span className="text-xs bg-cyan-600/20 text-cyan-300 px-2 py-1 rounded">
                            {connectedNodes.topics.length + connectedNodes.literature.length + 
                             connectedNodes.tasks.length + connectedNodes.cases.length}
                          </span>
                        )}
                      </h3>

                      {/* Inline Tag-Style Layout for All Connected Nodes */}
                      {(connectedNodes.topics.length + connectedNodes.literature.length + 
                        connectedNodes.tasks.length + connectedNodes.cases.length) > 0 ? (
                        <div className="flex flex-wrap gap-2 mb-6">
                          {/* Topics - Blue */}
                          {connectedNodes.topics.map((topic, index) => (
                            <div
                              key={`topic-${index}`}
                              className="flex items-center gap-1.5 px-2.5 py-1.5 bg-blue-600/10 border border-blue-600/30 rounded-md hover:bg-blue-600/20 transition-colors cursor-pointer text-sm"
                            >
                              <Brain size={14} className="text-blue-400 flex-shrink-0" />
                              <span className="text-blue-300">
                                {topic.title || topic.label || 'Untitled Topic'}
                              </span>
                            </div>
                          ))}

                          {/* Literature - Purple */}
                          {connectedNodes.literature.map((lit, index) => (
                            <div
                              key={`lit-${index}`}
                              className="flex items-center gap-1.5 px-2.5 py-1.5 bg-purple-600/10 border border-purple-600/30 rounded-md hover:bg-purple-600/20 transition-colors cursor-pointer text-sm"
                            >
                              <BookOpen size={14} className="text-purple-400 flex-shrink-0" />
                              <span className="text-purple-300">
                                {lit.title || lit.label || 'Untitled Literature'}
                              </span>
                            </div>
                          ))}

                          {/* Tasks - Amber */}
                          {connectedNodes.tasks.map((task, index) => (
                            <div
                              key={`task-${index}`}
                              className="flex items-center gap-1.5 px-2.5 py-1.5 bg-amber-600/10 border border-amber-600/30 rounded-md hover:bg-amber-600/20 transition-colors cursor-pointer text-sm"
                            >
                              <Target size={14} className="text-amber-400 flex-shrink-0" />
                              <span className="text-amber-300">
                                {task.title || task.label || task.description || 'Untitled Task'}
                              </span>
                            </div>
                          ))}

                          {/* Cases - Green */}
                          {connectedNodes.cases.map((caseNode, index) => (
                            <div
                              key={`case-${index}`}
                              className="flex items-center gap-1.5 px-2.5 py-1.5 bg-green-600/10 border border-green-600/30 rounded-md hover:bg-green-600/20 transition-colors cursor-pointer text-sm"
                            >
                              <Users size={14} className="text-green-400 flex-shrink-0" />
                              <span className="text-green-300">
                                {caseNode.case_id || caseNode.title || caseNode.primary_diagnosis || 'Untitled Case'}
                              </span>
                            </div>
                          ))}
                        </div>
                      ) : (
                        <div className="mb-6 p-4 bg-slate-700/20 rounded-lg border border-slate-600/50">
                          <p className="text-slate-400 text-sm italic text-center">
                            No connected nodes. Use the connection manager to link related topics, literature, tasks, or cases.
                          </p>
                        </div>
                      )}

                      {/* Notes Section */}
                      <div className="mb-6">
                        <NotesEditor
                          value={editData.notes || ''}
                          onChange={(notes) => setEditData(prev => ({ ...prev, notes }))}
                          placeholder="Add clinical notes, reflections, observations, or personal insights about this case..."
                        />
                      </div>

                      {/* Tags Section */}
                      <div className="mb-6">
                        <TagManager
                          tags={editData.tags || []}
                          onChange={(tags) => setEditData(prev => ({ ...prev, tags }))}
                          suggestions={[
                            'depression',
                            'anxiety',
                            'bipolar',
                            'schizophrenia',
                            'personality-disorder',
                            'substance-abuse',
                            'trauma',
                            'psychotherapy',
                            'pharmacotherapy',
                            'crisis-intervention',
                            'treatment-resistant',
                            'inpatient',
                            'outpatient',
                          ]}
                        />
                      </div>

                      <div className="mt-6 p-4 bg-slate-700/20 rounded-lg border border-slate-600">
                        <p className="text-slate-400 text-sm italic">
                          Connected nodes are automatically populated based on
                          mind map relationships. Use the connection manager to
                          link nodes together.
                        </p>
                      </div>
                    </motion.div>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default CaseModal;
